window.AUTH=window.AUTH||{};window.AUTH["05-705"]={"d":"05-705","id":"2006/05-705","n":"Global Crossing Telecommunications, Inc. v. Metrophones Telecommunications, Inc.","src":["osg"],"briefs":[{"k":"united-states","label":"Brief for the United States as amicus curiae supporting respondent","date":"","url":"https://www.justice.gov/osg/media/212846/dl?inline","side":"res","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/global-crossing-tele-comms-inc-v-metrophones-telecomms-inc-amicus-mertis","n":57}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep550/usrep550045/usrep550045.pdf","tr":true,"items":[{"t":"case","label":"Adams Fruit Co. v. Barrett","cite":"494 U.S. 638","y":1990,"id":"1989/88-2035","sc":1,"op":2,"sum":"Exclusivity provisions in state workers' compensation laws do not bar migrant workers from availing themselves of a private right of action under § 1854.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19"}},{"t":"case","label":"Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"op":4,"ar":1,"sum":"The Court held that there is no private right of action to enforce disparate-impact regulations promulgated under Title VI. \"Title VI itself directly reaches only instances of intentional discrimination,\" wrote Justice Scalia, \"[n]either as originally enacted nor as later amended does Title VI display an intent to create a freestanding private right of action to enforce regulations promulgated under [section 602].\" Justice John Paul Stevens filed a dissenting opinion, which was join by Justices David H. Souter, Ruth Bader Ginsburg, and Stephen G. Breyer.","sumSrc":"Oyez","by":{"0":"11, 13"}},{"t":"case","label":"American Library Ass’n v. FCC","cite":"406 F.3d 689","y":2005,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/406/689/","by":{"0":"26"}},{"t":"case","label":"American Pub. Commc’ns Council v. FCC","cite":"215 F.3d 51","y":2000,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/215/51/","op":1,"by":{"0":"3, 4, 17"}},{"t":"case","label":"APCC Servs., Inc. v. Sprint Commc’ns Co.","cite":"418 F.3d 1238","y":2005,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/418/1238/","op":7,"by":{"0":"6, 7"}},{"t":"case","label":"Ascom Commc’ns, Inc. v. Sprint Commc’ns Co.","cite":"15 F.C.C.R. 3223","y":2000,"url":"https://www.courtlistener.com/c/F.C.C.R./15/3223/","by":{"0":"28"}},{"t":"case","label":"AT&T Corp. v. Iowa Utils. Bd.","cite":"525 U.S. 366","y":1999,"id":"1998/97-826","sc":1,"sum":"In a complicated split opinion, the Court held that the FCC has rulemaking authority to uphold those provision of the Act in question. Despite the local nature of some of the LECs involved, the Court emphasized their interconnectivity with regional and national carriers. As such, the FCC could also reach local LEC markets and regulate their competitive business practices.","sumSrc":"Oyez","by":{"0":"14"}},{"t":"case","label":"AT&T v. MCI","cite":"9 F.C.C.R. 2688","y":1994,"court":"Com. Car. Bur.","url":"https://www.courtlistener.com/c/F.C.C.R./9/2688/","by":{"0":"21"}},{"t":"case","label":"Bell Atlantic Tel. Cos. v. FCC","cite":"79 F.3d 1195","y":1996,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/79/1195/","op":6,"ar":1,"by":{"0":"27"}},{"t":"case","label":"California Indep. Sys. Operator Corp. v. FERC","cite":"372 F.3d 395","y":2004,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/372/395/","by":{"0":"14"}},{"t":"case","label":"Chevron U.S.A. Inc. v. NRDC.","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"op":6,"ar":7,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"0":"6"}},{"t":"case","label":"Core Commc’ns, Inc. v. SBC Commc’ns, Inc.","cite":"18 F.C.C.R. 7568","y":2003,"url":"https://www.courtlistener.com/c/F.C.C.R./18/7568/","by":{"0":"25"}},{"t":"case","label":"Greene v. Sprint Commc’ns Co.","cite":"340 F.3d 1047","y":2003,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/340/1047/","op":2,"ar":1,"by":{"0":"5"}},{"t":"case","label":"Himmelman v. MCI Commc’ns Corp.","cite":"17 F.C.C.R. 5504","y":2002,"url":"https://www.courtlistener.com/c/F.C.C.R./17/5504/","by":{"0":"24"}},{"t":"case","label":"Illinois Pub. Telecomms. Ass’n v. FCC","cite":"117 F.3d 555","y":1997,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/117/555/","op":1,"by":{"0":"3"}},{"t":"case","label":"Louisiana Pub. Serv. Comm’n v. FCC","cite":"476 U.S. 355","y":1986,"id":"1985/84-871","sc":1,"op":2,"ar":3,"sum":"Section 152(b) bars federal pre-emption of state regulation over depreciation of dual jurisdiction property for intrastate ratemaking purposes.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"9, 28"}},{"t":"case","label":"MCI Telecomms. Corp. v. FCC","cite":"59 F.3d 1407","y":1995,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/59/1407/","op":4,"by":{"0":"23"}},{"t":"case","label":"Missouri Pac. R.R. v. Norwood","cite":"283 U.S. 249","y":1931,"id":"scdb/1930-051","sc":1,"op":4,"by":{"0":"14, 30"}},{"t":"case","label":"Motion Picture Ass’n of Am., Inc. v. FCC","cite":"309 F.3d 796","y":2002,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/309/796/","sum":"Striking down an FCC rule promulgated pursuant to Section 154(i).","sumSrc":"brief:0","by":{"0":"26"}},{"t":"case","label":"Motor Vehicle Mfrs. Ass’n v. State Farm Mut. Auto. Ins. Co.","cite":"463 U.S. 29","y":1983,"id":"1982/82-354","sc":1,"sum":"The Supreme Court held that the rescission of a standard should be reviewed based on whether the decision was arbitrary or capricious. Because the removal of a standard often entails the same level of policy changes as the promulgation of a law, it should be reviewed under the same tests.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"National Cable & Telecomms. Ass’n v. Brand X Internet Servs.","cite":"125 S. Ct. 2688","y":2005,"id":"2004/04-277","sc":1,"op":6,"ar":1,"sum":"The Court held that the FCC lawfully construed the Communications Act to not define cable broadband providers as \"telecommunications services.\" The Court held that the Ninth Circuit should have followed the Supreme Court's 1984 decision in Chevron v. Natural Resources Defense Council.","sumSrc":"Oyez","by":{"0":"14, 25"}},{"t":"case","label":"SBC Commc’ns, Inc. v. FCC","cite":"407 F.3d 1223","y":2005,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/407/1223/","by":{"0":"25"}},{"t":"case","label":"Sprint Corp. v. FCC","cite":"315 F.3d 369","y":2003,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/315/369/","by":{"0":"4, 18"}},{"t":"case","label":"Staton Holdings, Inc. v. MCI WorldCom Commc’ns, Inc.","cite":"19 F.C.C.R. 8699","y":2004,"court":"Enforcement Bureau","url":"https://www.courtlistener.com/c/F.C.C.R./19/8699/","by":{"0":"24"}},{"t":"case","label":"TRAC Commc’ns, Inc. v. Detroit Cellular Tel. Co.","cite":"5 F.C.C.R. 4647","y":1990,"url":"https://www.courtlistener.com/c/F.C.C.R./5/4647/","by":{"0":"23"}},{"t":"case","label":"United States v. Mead Corp.","cite":"533 U.S. 218","y":2001,"id":"2000/99-1434","sc":1,"op":1,"sum":"The Court held that the \"administrative implementation of a particular statutory provision qualifies for [the greatest level of deference accorded under Chevron U.S.A. Inc. v. Natural Resources Defense Council] when it appears that Congress delegated authority to the agency generally to make rules carrying the force of law, and that the agency interpretation claiming deference was promulgated in the exercise of that authority.\" Justice Souter wrote that \"a tariff classification has no claim to judicial deference under Chevron, there being no indication that Congress intended such a ruling to carry the force of law, but we hold that under Skidmore v. Swift & Co., the ruling is eligible to claim respect according to its persuasiveness.\".","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"WATS Int’l Corp. v. Group Long Distance (USA), Inc.","cite":"11 F.C.C.R. 3720","y":1995,"court":"Common Carrier Bureau","url":"https://www.courtlistener.com/c/F.C.C.R./11/3720/","by":{"0":"25"}},{"t":"usc","label":"42 U.S.C. § 2000d","url":"https://www.law.cornell.edu/uscode/text/42/2000d","stext":{"head":"§2000d. Prohibition against exclusion from participation in, denial of benefits of, and discrimination under federally assisted programs on ground of race, color, or national origin","paras":[[0,"No person in the United States shall, on the ground of race, color, or national origin, be excluded from participation in, be denied the benefits of, or be subjected to discrimination under any program or activity receiving Federal financial assistance."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000d?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§2000d. Prohibition against exclusion from participation in, denial of benefits of, and discrimination under federally assisted programs on ground of race, color, or national origin","tname":"The Public Health and Welfare","by":{"0":"11"}},{"t":"usc","label":"47 U.S.C. § 151","url":"https://www.law.cornell.edu/uscode/text/47/151","stext":{"head":"§151. Purposes of chapter; Federal Communications Commission created","paras":[[0,"For the purpose of regulating interstate and foreign commerce in communication by wire and radio so as to make available, so far as possible, to all the people of the United States, without discrimination on the basis of race, color, religion, national origin, or sex, a rapid, efficient, Nation-wide, and world-wide wire and radio communication service with adequate facilities at reasonable charges, for the purpose of the national defense, for the purpose of promoting safety of life and property through the use of wire and radio communications, and for the purpose of securing a more effective execution of this policy by centralizing authority heretofore granted by law to several agencies and by granting additional authority with respect to interstate and foreign commerce in wire and radio communication, there is created a commission to be known as the \"Federal Communications Commission\", which shall be constituted as hereinafter provided, and which shall execute and enforce the provisions of this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/47/151?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§151. Purposes of chapter; Federal Communications Commission created","tname":"Telecommunications","by":{"0":"22"}},{"t":"usc","label":"47 U.S.C. § 201","url":"https://www.law.cornell.edu/uscode/text/47/201","subs":["(a)","(b)","(b)(1)"],"stext":{"head":"§201. Service and charges","paras":[[0,"(a) It shall be the duty of every common carrier engaged in interstate or foreign communication by wire or radio to furnish such communication service upon reasonable request therefor; and, in accordance with the orders of the Commission, in cases where the Commission, after opportunity for hearing, finds such action necessary or desirable in the public interest, to establish physical connections with other carriers, to establish through routes and charges applicable thereto and the divisions of such charges, and to establish and provide facilities and regulations for operating such through routes."],[0,"(b) All charges, practices, classifications, and regulations for and in connection with such communication service, shall be just and reasonable, and any such charge, practice, classification, or regulation that is unjust or unreasonable is declared to be unlawful: Provided, That communications by wire or radio subject to this chapter may be classified into day, night, repeated, unrepeated, letter, commercial, press, Government, and such other classes as the Commission may decide to be just and reasonable, and different charges may be made for the different classes of communications: Provided further, That nothing in this chapter or in any other provision of law shall be construed to prevent a common carrier subject to this chapter from entering into or operating under any contract with any common carrier not subject to this chapter, for the exchange of their services, if the Commission is of the opinion that such contract is not contrary to the public interest: Provided further, That nothing in this chapter or in any other provision of law shall prevent a common carrier subject to this chapter from furnishing reports of positions of ships at sea to newspapers of general circulation, either at a nominal charge or without charge, provided the name of such common carrier is displayed along with such ship position reports. The Commission may prescribe such rules and regulations as may be necessary in the public interest to carry out the provisions of this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/47/201?type=usc&year=mostrecent&link-type=html"},"op":12,"ar":4,"head":"§201. Service and charges","tname":"Telecommunications","by":{"0":"22, 22, 22"}},{"t":"usc","label":"47 U.S.C. § 203","url":"https://www.law.cornell.edu/uscode/text/47/203","stext":{"head":"§203. Schedules of charges","paras":[[0,"(a) Filing; public display"],[0,"Every common carrier, except connecting carriers, shall, within such reasonable time as the Commission shall designate, file with the Commission and print and keep open for public inspection schedules showing all charges for itself and its connecting carriers for interstate and foreign wire or radio communication between the different points on its own system, and between points on its own system and points on the system of its connecting carriers or points on the system of any other carrier subject to this chapter when a through route has been established, whether such charges are joint or separate, and showing the classifications, practices, and regulations affecting such charges. Such schedules shall contain such other information, and be printed in such form, and be posted and kept open for public inspection in such places, as the Commission may by regulation require, and each such schedule shall give notice of its effective date; and such common carrier shall furnish such schedules to each of its connecting carriers, and such connecting carriers shall keep such schedules open for inspection in such public places as the Commission may require."],[0,"(b) Changes in schedule; discretion of Commission to modify requirements"],[0,"(1) No change shall be made in the charges, classifications, regulations, or practices which have been so filed and published except after one hundred and twenty days notice to the Commission and to the public, which shall be published in such form and contain such information as the Commission may by regulations prescribe."],[0,"(2) The Commission may, in its discretion and for good cause shown, modify any requirement made by or under the authority of this section either in particular instances or by general order applicable to special circumstances or conditions except that the Commission may not require the notice period specified in paragraph (1) to be more than one hundred and twenty days."],[0,"(c) Overcharges and rebates"],[0,"No carrier, unless otherwise provided by or under authority of this chapter, shall engage or participate in such communication unless schedules have been filed and published in accordance with the provisions of this chapter and with the regulations made thereunder; and no carrier shall (1) charge, demand, collect, or receive a greater or less or different compensation for such communication, or for any service in connection therewith, between the points named in any such schedule than the charges specified in the schedule then in effect, or (2) refund or remit by any means or device any portion of the charges so specified, or (3) extend to any person any privileges or facilities in such communication, or employ or enforce any classifications, regulations, or practices affecting such charges, except as specified in such schedule."],[0,"(d) Rejection or refusal"],[0,"The Commission may reject and refuse to file any schedule entered for filing which does not provide and give lawful notice of its effective date. Any schedule so rejected by the Commission shall be void and its use shall be unlawful."],[0,"(e) Penalty for violations"],[0,"In case of failure or refusal on the part of any carrier to comply with the provisions of this section or of any regulation or order made by the Commission thereunder, such carrier shall forfeit to the United States the sum of $6,000 for each such offense, and $300 for each and every day of the continuance of such offense."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/47/203?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§203. Schedules of charges","tname":"Telecommunications","by":{"0":"29"}},{"t":"usc","label":"47 U.S.C. § 206","url":"https://www.law.cornell.edu/uscode/text/47/206","stext":{"head":"§206. Carriers' liability for damages","paras":[[0,"In case any common carrier shall do, or cause or permit to be done, any act, matter, or thing in this chapter prohibited or declared to be unlawful, or shall omit to do any act, matter, or thing in this chapter required to be done, such common carrier shall be liable to the person or persons injured thereby for the full amount of damages sustained in consequence of any such violation of the provisions of this chapter, together with a reasonable counsel or attorney's fee, to be fixed by the court in every case of recovery, which attorney's fee shall be taxed and collected as part of the costs in the case."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/47/206?type=usc&year=mostrecent&link-type=html"},"op":13,"ar":3,"head":"§206. Carriers' liability for damages","tname":"Telecommunications","by":{"0":"4, 8, 9, 27, 4, 8, 9, 27"}},{"t":"usc","label":"47 U.S.C. § 207","url":"https://www.law.cornell.edu/uscode/text/47/207","stext":{"head":"§207. Recovery of damages","paras":[[0,"Any person claiming to be damaged by any common carrier subject to the provisions of this chapter may either make complaint to the Commission as hereinafter provided for, or may bring suit for the recovery of the damages for which such common carrier may be liable under the provisions of this chapter, in any district court of the United States of competent jurisdiction; but such person shall not have the right to pursue both such remedies."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/47/207?type=usc&year=mostrecent&link-type=html"},"op":26,"ar":1,"head":"§207. Recovery of damages","tname":"Telecommunications","by":{"0":"3, 5"}},{"t":"usc","label":"47 U.S.C. § 208","url":"https://www.law.cornell.edu/uscode/text/47/208","subs":["(a)"],"stext":{"head":"§208. Complaints to Commission; investigations; duration of investigation; appeal of order concluding investigation","paras":[[0,"(a) Any person, any body politic, or municipal organization, or State commission, complaining of anything done or omitted to be done by any common carrier subject to this chapter, in contravention of the provisions thereof, may apply to said Commission by petition which shall briefly state the facts, whereupon a statement of the complaint thus made shall be forwarded by the Commission to such common carrier, who shall be called upon to satisfy the complaint or to answer the same in writing within a reasonable time to be specified by the Commission. If such common carrier within the time specified shall make reparation for the injury alleged to have been caused, the common carrier shall be relieved of liability to the complainant only for the particular violation of law thus complained of. If such carrier or carriers shall not satisfy the complaint within the time specified or there shall appear to be any reasonable ground for investigating said complaint, it shall be the duty of the Commission to investigate the matters complained of in such manner and by such means as it shall deem proper. No complaint shall at any time be dismissed because of the absence of direct damage to the complaint."],[0,"(b)(1) Except as provided in paragraph (2), the Commission shall, with respect to any investigation under this section of the lawfulness of a charge, classification, regulation, or practice, issue an order concluding such investigation within 5 months after the date on which the complaint was filed."],[0,"(2) The Commission shall, with respect to any such investigation initiated prior to November 3, 1988, issue an order concluding the investigation not later than 12 months after November 3, 1988."],[0,"(3) Any order concluding an investigation under paragraph (1) or (2) shall be a final order and may be appealed under section 402(a) of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/47/208?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§208. Complaints to Commission; investigations; duration of investigation; appeal of order concluding investigation","tname":"Telecommunications","by":{"0":"3, 5, 3, 5"}},{"t":"usc","label":"47 U.S.C. § 271","url":"https://www.law.cornell.edu/uscode/text/47/271","by":{"0":"3, 5"}},{"t":"usc","label":"47 U.S.C. § 276","url":"https://www.law.cornell.edu/uscode/text/47/276","subs":["(b)","(b)(1)","(b)(1)(A)","(b)(1)(B)","(c)"],"stext":{"head":"§276. Provision of payphone service","paras":[[0,"(a) Nondiscrimination safeguards"],[0,"After the effective date of the rules prescribed pursuant to subsection (b), any Bell operating company that provides payphone service—"],[1,"(1) shall not subsidize its payphone service directly or indirectly from its telephone exchange service operations or its exchange access operations; and"],[1,"(2) shall not prefer or discriminate in favor of its payphone service."],[0,"(b) Regulations"],[0,"(1) Contents of regulations"],[1,"In order to promote competition among payphone service providers and promote the widespread deployment of payphone services to the benefit of the general public, within 9 months after February 8, 1996, the Commission shall take all actions necessary (including any reconsideration) to prescribe regulations that—"],[2,"(A) establish a compensation plan to ensure that all payphone service providers are fairly compensated, and all rates and charges are just and reasonable, for completed intrastate and interstate communications using their payphone or other calling device, except that emergency calls and telecommunications relay service calls for hearing disabled individuals shall not be subject to such compensation;"],[2,"(B) discontinue the intrastate and interstate carrier access charge payphone service elements and payments in effect on February 8, 1996, and all intrastate and interstate payphone subsidies from basic exchange and exchange access revenues, in favor of a compensation plan as specified in subparagraph (A);"],[2,"(C) prescribe a set of nonstructural safeguards for Bell operating company payphone service to implement the provisions of paragraphs (1) and (2) of subsection (a), which safeguards shall, at a minimum, include the nonstructural safeguards equal to those adopted in the Computer Inquiry-III (CC Docket No. 90–623) proceeding;"],[2,"(D) provide for Bell operating company payphone service providers to have the same right that independent payphone providers have to negotiate with the location provider on the location provider's selecting and contracting with, and, subject to the terms of any agreement with the location provider, to select and contract with, the carriers that carry interLATA calls from their payphones, unless the Commission determines in the rulemaking pursuant to this section that it is not in the public interest; and"],[2,"(E) provide for all payphone service providers to have the right to negotiate with the location provider on the location provider's selecting and contracting with, and, subject to the terms of any agreement with the location provider, to select and contract with, the carriers that carry intraLATA calls from their payphones."],[0,"(2) Public interest telephones"],[1,"In the rulemaking conducted pursuant to paragraph (1), the Commission shall determine whether public interest payphones, which are provided in the interest of public health, safety, and welfare, in locations where there would otherwise not be a payphone, should be maintained, and if so, ensure that such public interest payphones are supported fairly and equitably."],[0,"(3) Existing contracts"],[1,"Nothing in this section shall affect any existing contracts between location providers and payphone service providers or interLATA or intraLATA carriers that are in force and effect as of February 8, 1996."],[0,"(c) State preemption"],[0,"To the extent that any State requirements are inconsistent with the Commission's regulations, the Commission's regulations on such matters shall preempt such State requirements."],[0,"(d) \"Payphone service\" defined"],[0,"As used in this section, the term \"payphone service\" means the provision of public or semi-public pay telephones, the provision of inmate telephone service and advanced communications services described in subparagraphs (A), (B), (D), and (E) of section 153(1) of this title in correctional institutions, and any ancillary services."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/47/276?type=usc&year=mostrecent&link-type=html"},"op":12,"ar":5,"head":"§276. Provision of payphone service","tname":"Telecommunications","by":{"0":"15, 15, 15, 3, 3, 30"}},{"t":"usc","label":"47 U.S.C. § 226","url":"https://www.law.cornell.edu/uscode/text/47/226","subs":["(c)(1)(B)","(e)(2)"],"stext":{"head":"§226. Telephone operator services","paras":[[0,"(a) Definitions"],[0,"As used in this section—"],[1,"(1) The term \"access code\" means a sequence of numbers that, when dialed, connect the caller to the provider of operator services associated with that sequence."],[1,"(2) The term \"aggregator\" means any person that, in the ordinary course of its operations, makes telephones available to the public or to transient users of its premises, for interstate telephone calls using a provider of operator services."],[1,"(3) The term \"call splashing\" means the transfer of a telephone call from one provider of operator services to another such provider in such a manner that the subsequent provider is unable or unwilling to determine the location of the origination of the call and, because of such inability or unwillingness, is prevented from billing the call on the basis of such location."],[1,"(4) The term \"consumer\" means a person initiating any interstate telephone call using operator services."],[1,"(5) The term \"equal access\" has the meaning given that term in Appendix B of the Modification of Final Judgment entered August 24, 1982, in United States v. Western Electric, Civil Action No. 82–0192 (United States District Court, District of Columbia), as amended by the Court in its orders issued prior to October 17, 1990."],[1,"(6) The term \"equal access code\" means an access code that allows the public to obtain an equal access connection to the carrier associated with that code."],[1,"(7) The term \"operator services\" means any interstate telecommunications service initiated from an aggregator location that includes, as a component, any automatic or live assistance to a consumer to arrange for billing or completion, or both, of an interstate telephone call through a method other than—"],[2,"(A) automatic completion with billing to the telephone from which the call originated; or"],[2,"(B) completion through an access code used by the consumer, with billing to an account previously established with the carrier by the consumer."],[1,"(8) The term \"presubscribed provider of operator services\" means the interstate provider of operator services to which the consumer is connected when the consumer places a call using a provider of operator services without dialing an access code."],[1,"(9) The term \"provider of operator services\" means any common carrier that provides operator services or any other person determined by the Commission to be providing operator services."],[0,"(b) Requirements for providers of operator services"],[0,"(1) In general"],[1,"Beginning not later than 90 days after October 17, 1990, each provider of operator services shall, at a minimum—"],[2,"(A) identify itself, audibly and distinctly, to the consumer at the beginning of each telephone call and before the consumer incurs any charge for the call;"],[2,"(B) permit the consumer to terminate the telephone call at no charge before the call is connected;"],[2,"(C) disclose immediately to the consumer, upon request and at no charge to the consumer—"],[3,"(i) a quote of its rates or charges for the call;"],[3,"(ii) the methods by which such rates or charges will be collected; and"],[3,"(iii) the methods by which complaints concerning such rates, charges, or collection practices will be resolved;"],[2,"(D) ensure, by contract or tariff, that each aggregator for which such provider is the presubscribed provider of operator services is in compliance with the requirements of subsection (c) and, if applicable, subsection (e)(1);"],[2,"(E) withhold payment (on a location-by-location basis) of any compensation, including commissions, to aggregators if such provider reasonably believes that the aggregator (i) is blocking access by means of \"950\" or \"800\" numbers to interstate common carriers in violation of subsection (c)(1)(B) or (ii) is blocking access to equal access codes in violation of rules the Commission may prescribe under subsection (e)(1);"],[2,"(F) not bill for unanswered telephone calls in areas where equal access is available;"],[2,"(G) not knowingly bill for unanswered telephone calls where equal access is not available;"],[2,"(H) not engage in call splashing, unless the consumer requests to be transferred to another provider of operator services, the consumer is informed prior to incurring any charges that the rates for the call may not reflect the rates from the actual originating location of the call, and the consumer then consents to be transferred; and"],[2,"(I) except as provided in subparagraph (H), not bill for a call that does not reflect the location of the origination of the call."],[0,"(2) Additional requirements for first 3 years"],[1,"In addition to meeting the requirements of paragraph (1), during the 3-year period beginning on the date that is 90 days after October 17, 1990, each presubscribed provider of operator services shall identify itself audibly and distinctly to the consumer, not only as required in paragraph (1)(A), but also for a second time before connecting the call and before the consumer incurs any charge."],[0,"(c) Requirements for aggregators"],[0,"(1) In general"],[1,"Each aggregator, beginning not later than 90 days after October 17, 1990, shall—"],[2,"(A) post on or near the telephone instrument, in plain view of consumers—"],[3,"(i) the name, address, and toll-free telephone number of the provider of operator services;"],[3,"(ii) a written disclosure that the rates for all operator-assisted calls are available on request, and that consumers have a right to obtain access to the interstate common carrier of their choice and may contact their preferred interstate common carriers for information on accessing that carrier's service using that telephone; and"],[3,"(iii) the name and address of the enforcement division of the Common Carrier Bureau of the Commission, to which the consumer may direct complaints regarding operator services;"],[2,"(B) ensure that each of its telephones presubscribed to a provider of operator services allows the consumer to use \"800\" and \"950\" access code numbers to obtain access to the provider of operator services desired by the consumer; and"],[2,"(C) ensure that no charge by the aggregator to the consumer for using an \"800\" or \"950\" access code number, or any other access code number, is greater than the amount the aggregator charges for calls placed using the presubscribed provider of operator services."],[0,"(2) Effect of State law or regulation"],[1,"The requirements of paragraph (1)(A) shall not apply to an aggregator in any case in which State law or State regulation requires the aggregator to take actions that are substantially the same as those required in paragraph (1)(A)."],[0,"(d) General rulemaking required"],[0,"(1) Rulemaking proceeding"],[1,"The Commission shall conduct a rulemaking proceeding pursuant to this subchapter to prescribe regulations to—"],[2,"(A) protect consumers from unfair and deceptive practices relating to their use of operator services to place interstate telephone calls; and"],[2,"(B) ensure that consumers have the opportunity to make informed choices in making such calls."],[0,"(2) Contents of regulations"],[1,"The regulations prescribed under this section shall—"],[2,"(A) contain provisions to implement each of the requirements of this section, other than the requirements established by the rulemaking under subsection (e) on access and compensation; and"],[2,"(B) contain such other provisions as the Commission determines necessary to carry out this section and the purposes and policies of this section."],[0,"(3) Additional requirements to be implemented by regulations"],[1,"The regulations prescribed under this section shall, at a minimum—"],[2,"(A) establish minimum standards for providers of operator services and aggregators to use in the routing and handling of emergency telephone calls; and"],[2,"(B) establish a policy for requiring providers of operator services to make public information about recent changes in operator services and choices available to consumers in that market."],[0,"(e) Separate rulemaking on access and compensation"],[0,"(1) Access"],[1,"The Commission,1 shall require—"],[2,"(A) that each aggregator ensure within a reasonable time that each of its telephones presubscribed to a provider of operator services allows the consumer to obtain access to the provider of operator services desired by the consumer through the use of an equal access code; or"],[2,"(B) that all providers of operator services, within a reasonable time, make available to their customers a \"950\" or \"800\" access code number for use in making operator services calls from anywhere in the United States; or"],[2,"(C) that the requirements described under both subparagraphs (A) and (B) apply."],[0,"(2) Compensation"],[1,"The Commission shall consider the need to prescribe compensation (other than advance payment by consumers) for owners of competitive public pay telephones for calls routed to providers of operator services that are other than the presubscribed provider of operator services for such telephones. Within 9 months after October 17, 1990, the Commission shall reach a final decision on whether to prescribe such compensation."],[0,"(f) Technological capability of equipment"],[0,"Any equipment and software manufactured or imported more than 18 months after October 17, 1990, and installed by any aggregator shall be technologically capable of providing consumers with access to interstate providers of operator services through the use of equal access codes."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/47/226?type=usc&year=mostrecent&link-type=html"},"op":1,"ar":2,"head":"§226. Telephone operator services","tname":"Telecommunications","by":{"0":"2, 2, 16"}},{"t":"usc","label":"28 U.S.C. § 2342","url":"https://www.law.cornell.edu/uscode/text/28/2342","subs":["(1)"],"by":{"0":"16"}},{"t":"usc","label":"47 U.S.C. § 152","url":"https://www.law.cornell.edu/uscode/text/47/152","subs":["(b)"],"by":{"0":"28"}},{"t":"usc","label":"47 U.S.C. § 154","url":"https://www.law.cornell.edu/uscode/text/47/154","subs":["(i)"],"by":{"0":"26"}},{"t":"usc","label":"47 U.S.C. § 227","url":"https://www.law.cornell.edu/uscode/text/47/227","subs":["(c)(1)(B)"],"stext":{"head":"§227. Restrictions on use of telephone equipment","paras":[[0,"(a) Definitions"],[0,"As used in this section—"],[1,"(1) The term \"automatic telephone dialing system\" means equipment which has the capacity—"],[2,"(A) to store or produce telephone numbers to be called, using a random or sequential number generator; and"],[2,"(B) to dial such numbers."],[1,"(2) The term \"established business relationship\", for purposes only of subsection (b)(1)(C)(i), shall have the meaning given the term in section 64.1200 of title 47, Code of Federal Regulations, as in effect on January 1, 2003, except that—"],[2,"(A) such term shall include a relationship between a person or entity and a business subscriber subject to the same terms applicable under such section to a relationship between a person or entity and a residential subscriber; and"],[2,"(B) an established business relationship shall be subject to any time limitation established pursuant to paragraph (2)(G)).1"],[1,"(3) The term \"telephone facsimile machine\" means equipment which has the capacity (A) to transcribe text or images, or both, from paper into an electronic signal and to transmit that signal over a regular telephone line, or (B) to transcribe text or images (or both) from an electronic signal received over a regular telephone line onto paper."],[1,"(4) The term \"telephone solicitation\" means the initiation of a telephone call or message for the purpose of encouraging the purchase or rental of, or investment in, property, goods, or services, which is transmitted to any person, but such term does not include a call or message (A) to any person with that person's prior express invitation or permission, (B) to any person with whom the caller has an established business relationship, or (C) by a tax exempt nonprofit organization."],[1,"(5) The term \"unsolicited advertisement\" means any material advertising the commercial availability or quality of any property, goods, or services which is transmitted to any person without that person's prior express invitation or permission, in writing or otherwise."],[0,"(b) Restrictions on use of automated telephone equipment"],[0,"(1) Prohibitions"],[1,"It shall be unlawful for any person within the United States, or any person outside the United States if the recipient is within the United States—"],[2,"(A) to make any call (other than a call made for emergency purposes or made with the prior express consent of the called party) using any automatic telephone dialing system or an artificial or prerecorded voice—"],[3,"(i) to any emergency telephone line (including any \"911\" line and any emergency line of a hospital, medical physician or service office, health care facility, poison control center, or fire protection or law enforcement agency);"],[3,"(ii) to the telephone line of any guest room or patient room of a hospital, health care facility, elderly home, or similar establishment; or"],[3,"(iii) to any telephone number assigned to a paging service, cellular telephone service, specialized mobile radio service, or other radio common carrier service, or any service for which the called party is charged for the call, unless such call is made solely to collect a debt owed to or guaranteed by the United States;"],[2,"(B) to initiate any telephone call to any residential telephone line using an artificial or prerecorded voice to deliver a message without the prior express consent of the called party, unless the call is initiated for emergency purposes, is made solely pursuant to the collection of a debt owed to or guaranteed by the United States, or is exempted by rule or order by the Commission under paragraph (2)(B);"],[2,"(C) to use any telephone facsimile machine, computer, or other device to send, to a telephone facsimile machine, an unsolicited advertisement, unless—"],[3,"(i) the unsolicited advertisement is from a sender with an established business relationship with the recipient;"],[3,"(ii) the sender obtained the number of the telephone facsimile machine through—"],[4,"(I) the voluntary communication of such number, within the context of such established business relationship, from the recipient of the unsolicited advertisement, or"],[4,"(II) a directory, advertisement, or site on the Internet to which the recipient voluntarily agreed to make available its facsimile number for public distribution,"],[0,"except that this clause shall not apply in the case of an unsolicited advertisement that is sent based on an established business relationship with the recipient that was in existence before July 9, 2005, if the sender possessed the facsimile machine number of the recipient before July 9, 2005; and"],[3,"(iii) the unsolicited advertisement contains a notice meeting the requirements under paragraph (2)(D),"],[2,"except that the exception under clauses (i) and (ii) shall not apply with respect to an unsolicited advertisement sent to a telephone facsimile machine by a sender to whom a request has been made not to send future unsolicited advertisements to such telephone facsimile machine that complies with the requirements under paragraph (2)(E); or"],[2,"(D) to use an automatic telephone dialing system in such a way that two or more telephone lines of a multi-line business are engaged simultaneously."],[0,"(2) Regulations; exemptions and other provisions"],[1,"The Commission shall prescribe regulations to implement the requirements of this subsection. In implementing the requirements of this subsection, the Commission—"],[2,"(A) shall consider prescribing regulations to allow businesses to avoid receiving calls made using an artificial or prerecorded voice to which they have not given their prior express consent;"],[2,"(B) may, by rule or order, exempt from the requirements of paragraph (1)(B) of this subsection, subject to such conditions as the Commission may prescribe—"],[3,"(i) calls that are not made for a commercial purpose; and"],[3,"(ii) such classes or categories of calls made for commercial purposes as the Commission determines—"],[4,"(I) will not adversely affect the privacy rights that this section is intended to protect; and"],[4,"(II) do not include the transmission of any unsolicited advertisement;"],[2,"(C) may, by rule or order, exempt from the requirements of paragraph (1)(A)(iii) of this subsection calls to a telephone number assigned to a cellular telephone service that are not charged to the called party, subject to such conditions as the Commission may prescribe as necessary in the interest of the privacy rights this section is intended to protect;"],[2,"(D) shall provide that a notice contained in an unsolicited advertisement complies with the requirements under this subparagraph only if—"],[3,"(i) the notice is clear and conspicuous and on the first page of the unsolicited advertisement;"],[3,"(ii) the notice states that the recipient may make a request to the sender of the unsolicited advertisement not to send any future unsolicited advertisements to a telephone facsimile machine or machines and that failure to comply, within the shortest reasonable time, as determined by the Commission, with such a request meeting the requirements under subparagraph (E) is unlawful;"],[3,"(iii) the notice sets forth the requirements for a request under subparagraph (E);"],[3,"(iv) the notice includes—"],[4,"(I) a domestic contact telephone and facsimile machine number for the recipient to transmit such a request to the sender; and"],[4,"(II) a cost-free mechanism for a recipient to transmit a request pursuant to such notice to the sender of the unsolicited advertisement; the Commission shall by rule require the sender to provide such a mechanism and may, in the discretion of the Commission and subject to such conditions as the Commission may prescribe, exempt certain classes of small business senders, but only if the Commission determines that the costs to such class are unduly burdensome given the revenues generated by such small businesses;"],[3,"(v) the telephone and facsimile machine numbers and the cost-free mechanism set forth pursuant to clause (iv) permit an individual or business to make such a request at any time on any day of the week; and"],[3,"(vi) the notice complies with the requirements of subsection (d);"],[2,"(E) shall provide, by rule, that a request not to send future unsolicited advertisements to a telephone facsimile machine complies with the requirements under this subparagraph only if—"],[3,"(i) the request identifies the telephone number or numbers of the telephone facsimile machine or machines to which the request relates;"],[3,"(ii) the request is made to the telephone or facsimile number of the sender of such an unsolicited advertisement provided pursuant to subparagraph (D)(iv) or by any other method of communication as determined by the Commission; and"],[3,"(iii) the person making the request has not, subsequent to such request, provided express invitation or permission to the sender, in writing or otherwise, to send such advertisements to such person at such telephone facsimile machine;"],[2,"(F) may, in the discretion of the Commission and subject to such conditions as the Commission may prescribe, allow professional or trade associations that are tax-exempt nonprofit organizations to send unsolicited advertisements to their members in furtherance of the association's tax-exempt purpose that do not contain the notice required by paragraph (1)(C)(iii), except that the Commission may take action under this subparagraph only—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/47/227?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§227. Restrictions on use of telephone equipment","tname":"Telecommunications","by":{"0":"30"}},{"t":"usc","label":"47 U.S.C. § 401","url":"https://www.law.cornell.edu/uscode/text/47/401","subs":["(a)"],"by":{"0":"16"}},{"t":"usc","label":"47 U.S.C. § 502","url":"https://www.law.cornell.edu/uscode/text/47/502","by":{"0":"26, 26"}},{"t":"usc","label":"47 U.S.C. § 503","url":"https://www.law.cornell.edu/uscode/text/47/503","subs":["(b)(1)(A)"],"stext":{"head":"§503. Forfeitures","paras":[[0,"(a) Rebates and offsets"],[0,"Any person who shall deliver messages for interstate or foreign transmission to any carrier, or for whom as sender or receiver, any such carrier shall transmit any interstate or foreign wire or radio communication, who shall knowingly by employee, agent, officer, or otherwise, directly or indirectly, by or through any means or device whatsoever, receive or accept from such common carrier any sum of money or any other valuable consideration as a rebate or offset against the regular charges for transmission of such messages as fixed by the schedules of charges provided for in this chapter, shall in addition to any other penalty provided by this chapter forfeit to the United States a sum of money three times the amount of money so received or accepted and three times the value of any other consideration so received or accepted, to be ascertained by the trial court; and in the trial of said action all such rebates or other considerations so received or accepted for a period of six years prior to the commencement of the action, may be included therein, and the amount recovered shall be three times the total amount of money, or three times the total value of such consideration, so received or accepted, or both, as the case may be."],[0,"(b) Activities constituting violations authorizing imposition of forfeiture penalty; amount of penalty; procedures applicable; persons subject to penalty; liability exemption period"],[0,"(1) Any person who is determined by the Commission, in accordance with paragraph (3) or (4) of this subsection, to have—"],[1,"(A) willfully or repeatedly failed to comply substantially with the terms and conditions of any license, permit, certificate, or other instrument or authorization issued by the Commission;"],[1,"(B) willfully or repeatedly failed to comply with any of the provisions of this chapter or of any rule, regulation, or order issued by the Commission under this chapter or under any treaty, convention, or other agreement to which the United States is a party and which is binding upon the United States;"],[1,"(C) violated any provision of section 317(c) or 509(a) of this title; or"],[1,"(D) violated any provision of section 1304, 1343, 1464, or 2252 of title 18;"],[0,"shall be liable to the United States for a forfeiture penalty. A forfeiture penalty under this subsection shall be in addition to any other penalty provided for by this chapter; except that this subsection shall not apply to any conduct which is subject to forfeiture under subchapter II, part II or III of subchapter III, or section 507 of this title."],[0,"(2)(A) If the violator is (i) a broadcast station licensee or permittee, (ii) a cable television operator, or (iii) an applicant for any broadcast or cable television operator license, permit, certificate, or other instrument or authorization issued by the Commission, the amount of any forfeiture penalty determined under this section shall not exceed $25,000 for each violation or each day of a continuing violation, except that the amount assessed for any continuing violation shall not exceed a total of $250,000 for any single act or failure to act described in paragraph (1) of this subsection."],[0,"(B) If the violator is a common carrier subject to the provisions of this chapter or an applicant for any common carrier license, permit, certificate, or other instrument of authorization issued by the Commission, the amount of any forfeiture penalty determined under this subsection shall not exceed $100,000 for each violation or each day of a continuing violation, except that the amount assessed for any continuing violation shall not exceed a total of $1,000,000 for any single act or failure to act described in paragraph (1) of this subsection."],[0,"(C) Notwithstanding subparagraph (A), if the violator is—"],[1,"(i)(I) a broadcast station licensee or permittee; or"],[1,"(II) an applicant for any broadcast license, permit, certificate, or other instrument or authorization issued by the Commission; and"],[1,"(ii) determined by the Commission under paragraph (1) to have broadcast obscene, indecent, or profane language,1 the amount of any forfeiture penalty determined under this subsection shall not exceed $325,000 for each violation or each day of a continuing violation, except that the amount assessed for any continuing violation shall not exceed a total of $3,000,000 for any single act or failure to act."],[0,"(D) In any case not covered in subparagraph (A), (B), or (C), the amount of any forfeiture penalty determined under this subsection shall not exceed $10,000 for each violation or each day of a continuing violation, except that the amount assessed for any continuing violation shall not exceed a total of $75,000 for any single act or failure to act described in paragraph (1) of this subsection."],[0,"(E) The amount of such forfeiture penalty shall be assessed by the Commission, or its designee, by written notice. In determining the amount of such a forfeiture penalty, the Commission or its designee shall take into account the nature, circumstances, extent, and gravity of the violation and, with respect to the violator, the degree of culpability, any history of prior offenses, ability to pay, and such other matters as justice may require."],[0,"(F) Subject to paragraph (5) of this section, if the violator is a manufacturer or service provider subject to the requirements of section 255, 617, or 619 of this title, and is determined by the Commission to have violated any such requirement, the manufacturer or provider shall be liable to the United States for a forfeiture penalty of not more than $100,000 for each violation or each day of a continuing violation, except that the amount assessed for any continuing violation shall not exceed a total of $1,000,000 for any single act or failure to act."],[0,"(3)(A) At the discretion of the Commission, a forfeiture penalty may be determined against a person under this subsection after notice and an opportunity for a hearing before the Commission or an administrative law judge thereof in accordance with section 554 of title 5. Any person against whom a forfeiture penalty is determined under this paragraph may obtain review thereof pursuant to section 402(a) of this title."],[0,"(B) If any person fails to pay an assessment of a forfeiture penalty determined under subparagraph (A) of this paragraph, after it has become a final and unappealable order or after the appropriate court has entered final judgment in favor of the Commission, the Commission shall refer the matter to the Attorney General of the United States, who shall recover the amount assessed in any appropriate district court of the United States. In such action, the validity and appropriateness of the final order imposing the forfeiture penalty shall not be subject to review."],[0,"(4) Except as provided in paragraph (3) of this subsection, no forfeiture penalty shall be imposed under this subsection against any person unless and until—"],[1,"(A) the Commission issues a notice of apparent liability, in writing, with respect to such person;"],[1,"(B) such notice has been received by such person, or until the Commission has sent such notice to the last known address of such person, by registered or certified mail; and"],[1,"(C) such person is granted an opportunity to show, in writing, within such reasonable period of time as the Commission prescribes by rule or regulation, why no such forfeiture penalty should be imposed."],[0,"Such a notice shall (i) identify each specific provision, term, and condition of any Act, rule, regulation, order, treaty, convention, or other agreement, license, permit, certificate, instrument, or authorization which such person apparently violated or with which such person apparently failed to comply; (ii) set forth the nature of the act or omission charged against such person and the facts upon which such charge is based; and (iii) state the date on which such conduct occurred. Any forfeiture penalty determined under this paragraph shall be recoverable pursuant to section 504(a) of this title."],[0,"(5) No forfeiture liability shall be determined under this subsection against any person, if such person does not hold a license, permit, certificate, or other authorization issued by the Commission, and if such person is not an applicant for a license, permit, certificate, or other authorization issued by the Commission, unless, prior to the notice required by paragraph (3) of this subsection or the notice of apparent liability required by paragraph (4) of this subsection, such person (A) is sent a citation of the violation charged; (B) is given a reasonable opportunity for a personal interview with an official of the Commission, at the field office of the Commission which is nearest to such person's place of residence; and (C) subsequently engages in conduct of the type described in such citation. The provisions of this paragraph shall not apply, however, if the person involved is engaging in activities for which a license, permit, certificate, or other authorization is required, or is a cable television system operator, if the person involved is transmitting on frequencies assigned for use in a service in which individual station operation is authorized by rule pursuant to section 307(e) of this title, or in the case of violations of section 303(q) of this title, if the person involved is a nonlicensee tower owner who has previously received notice of the obligations imposed by section 303(q) of this title from the Commission or the permittee or licensee who uses that tower. Whenever the requirements of this paragraph are satisfied with respect to a particular person, such person shall not be entitled to receive any additional citation of the violation charged, with respect to any conduct of the type described in the citation sent under this paragraph."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/47/503?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§503. Forfeitures","tname":"Telecommunications","by":{"0":"26, 26"}}]};